"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["53201"],{51604(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grafo_formulario.cita_atributo_do_candidato","status":422,"titulo":"A regra do formul\xe1rio cita fato calculado de atributos do candidato"},"descricao":{"codigo":"uniplus.grafo_formulario.cita_atributo_do_candidato","requisitos":[],"oQueAconteceu":["Uma regra do formul\xe1rio cita um fato que o sistema calcula a partir de atributos do candidato e que n\xe3o declara as depend\xeancias dele, como a renda per capita. O formul\xe1rio n\xe3o tem como saber em que ponto da coleta esse fato fica conhecido, e por isso nenhuma regra o cita. Os fatos calculados que declaram as depend\xeancias, como a faixa et\xe1ria, passam, e a confer\xeancia das depend\xeancias os trata como o derivado por regra. A mensagem \xe9 \\"O fato \'`{c\xf3digo\\\\}`\' \xe9 calculado pelo sistema a partir de atributos do candidato sem depend\xeancias declaradas e n\xe3o pode ser citado em regra do formul\xe1rio.\\"","A confer\xeancia vale para as regras de item e de grupo (pr\xe9-condi\xe7\xe3o, obrigatoriedade, restri\xe7\xf5es e impedimento), para a exibi\xe7\xe3o das se\xe7\xf5es e para a exibi\xe7\xe3o e a obrigatoriedade dos termos; nos modelos, tamb\xe9m para a condi\xe7\xe3o dos documentos exigidos. Nos modelos, a recusa vem na lista `errors`, com `field` igual ao da regra que cita, como `conteudo.paginas[i].exibicao`. Nas grava\xe7\xf5es do processo, o `field` \xe9 `paginas[i].exibicao` na se\xe7\xe3o, `termos[i].exibicao` ou `termos[i].predicadoObrigatoriedade` no termo, e `itens[i]` ou `grupos[i]` no item ou no grupo. Nada \xe9 gravado.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire a cita\xe7\xe3o ao fato calculado. Se a decis\xe3o depende da mesma informa\xe7\xe3o, use na regra o fato que o candidato responde, ou um dos fatos calculados que declaram as depend\xeancias."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo","Grava\xe7\xe3o dos termos do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grafo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);